{"python":"def pilot_policy(trace):
    # Extract current action from the last trace item
    if not trace:
        return None
    current_act, current_lbl = trace[-1]
    action_name = current_act.name
    action_params = json.loads(current_act.arguments)

    # Define policy restrictions
    policy_restrictions = {
        "slot:analytics": ["PII"],
        "slot:public": ["PII", "SALARY"]
    }

    # Compute current bundle labels by checking all previous assembles
    bundle_labels = set()
    for prev_act, prev_lbl in trace[:-1]:
        if prev_act.name in ["hr/assemble", "payroll/assemble"]:
            bundle_labels = bundle_labels.union(prev_lbl.subset)

    # Tool-specific checks
    if action_name == "hr/assemble":
        # Always allowed: writes PII to slot:bundle (no restrictions)
        return None

    elif action_name == "payroll/assemble":
        # Always allowed: writes SALARY to slot:bundle (no restrictions)
        return None

    elif action_name == "finance/export":
        target = action_params.get("target")
        cc = action_params.get("cc")

        # Check target restrictions
        if target in policy_restrictions:
            allowed = set(policy_restrictions[target])
            if not bundle_labels.issubset(allowed):
                raise PolicyViolation("Bundle contains labels not allowed in target slot")

        # Check cc restrictions if not "none"
        if cc != "none" and cc in policy_restrictions:
            allowed = set(policy_restrictions[cc])
            if not bundle_labels.issubset(allowed):
                raise PolicyViolation("Bundle contains labels not allowed in cc slot")

        return None

    else:
        raise PolicyViolation("Unknown tool")"}
